mapper.sql:
FROM chkList
     LEFT JOIN ics15_checklist_write ON ( ics15_checklist_id = ics10_checklist_id
                                      AND ics15_company_id   = #{companyId}
                                      AND ics15_person_id    = person_id
                                      AND ics15_cycle_type   = #{cycleType}
                                      AND ics15_check_yyyymm = TO_CHAR(#{stdDate}::date,'YYYY.MM') )

mapper.select:
SELECT sys12_day::date
  FROM sys12_calendar
 WHERE sys12_company_id          = #{companyId}
   AND to_char(sys12_day,'yyyy') = #{year}
   AND sys12_day                 = f_get_last_day(sys12_day::date)
 ORDER BY sys12_day

SELECT sys12_day::date
  FROM sys12_calendar
 WHERE sys12_company_id          = #{companyId}
   AND to_char(sys12_day,'yyyy') = #{year}
   AND sys12_day                 = f_get_last_day((f_get_quarter_date(sys12_day::date,'1') + interval '+3month')::date)
 ORDER BY sys12_day

SELECT ics10_checklist_id AS checklist_id , ics11_company_id AS company_id , ics10_content AS content , ics10_criterion AS criterion , ics10_seq AS seq , ics10_checklist_m_class_id AS checklist_m_class_id , ics21_checklist_l_class_id AS check_l_class_id , ics10_check_l_class_nm AS check_l_class_name , ics10_check_m_class_nm AS check_m_class_name , ics15_checklist_write_id AS checklist_write_id , CASE WHEN ics15_answer_cd IS NOT NULL THEN f_cdnm('AnswerCode', ics15_answer_cd, ics11_company_id, #{stdDate}) ELSE '' END ||CASE WHEN ics15_reason IS NOT NULL THEN ' ('||ics15_reason||')' ELSE '' END AS reason , org_nm AS org_name , person_id AS person_id , person_nm AS person_name , COALESCE(ics15_fix_yn,'false') = 'true' AS fix_yn , confirmer.emp00_kor_nm AS confirmer_name , COALESCE(ics15_confirm_yn,'false') = 'true' AS confirm_yn
LEFT JOIN getPerson(#{companyId}, #{stdDate}) confirmer ON confirmer.emp00_person_id = COALESCE(ics15_confirmer_id, confirmer_id) WHERE 1=1
ORDER BY ics10_check_l_class_seq, ics10_check_m_class_seq, ics10_seq, ics10_content, org_nm, person_nm LIMIT #{limit} OFFSET #{offset}
